package com.spidy.servlet;import com.spidy.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/missions") public class MissionServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws IOException,ServletException{if(!Auth.student(r)){p.sendRedirect("login.jsp");return;}try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("SELECT m.id,m.title,m.description,m.category,m.difficulty,m.option_a,m.option_b,m.option_c,m.option_d,m.xp_reward FROM missions m WHERE NOT EXISTS(SELECT 1 FROM mission_submissions x WHERE x.mission_id=m.id AND x.user_id=?) ORDER BY m.id DESC")){s.setInt(1,(Integer)r.getSession().getAttribute("userId"));r.setAttribute("missions",s.executeQuery());r.getRequestDispatcher("missions.jsp").forward(r,p);}catch(Exception e){r.getSession().setAttribute("msg",e.getMessage());p.sendRedirect("dashboard");}}}
